class Fibs implements Iterator<Long> {     // single-use pull cursor
    private long a = 0, b = 1;
    public boolean hasNext() { return true; }
    public Long next() { long r = a; a = b; b += r; return r; }
}

Iterator<Long> it = new Fibs();          // for-each or StreamSupport drives it
